behaviors.source:
on tick
  let bow = water_height(34.0 + 15, 330.0 - 4)
  let stern = water_height(34.0 - 15, 330.0 + 4)
  let port = water_height(34.0 + 1, 330.0 + 3.5)
  let starboard = water_height(34.0 - 1, 330.0 - 3.5)
  let mid = (bow + stern + port + starboard) / 4
  self.position = (34.0, mid * 0.85 - 0.15, 330.0)
  self.rotation = ((port - starboard) * 3.5, 75 + sin(time * 0.07) * 2.5, (stern - bow) * 2.0)
end
